from typing import Any, Iterator, Tuple


def _iter_between(ledger: Any, account: str, start: datetime.date, end: datetime.date) -> Iterator[Tuple[datetime.date, str, int]]:
    """Yield (date, acct, amount) entries in [start, end) for a given account."""
    try:
        for d, acct, amount in ledger.between(start, end):
            if acct == account and start <= d < end:
                yield d, acct, amount
        return
    except Exception:
        pass

    for d, acct, amount in ledger.entries():
        if acct == account and start <= d < end:
            yield d, acct, amount


def year_total(ledger: Any, account: str, year: int) -> int:
    start = datetime.date(year, 1, 1)
    end = datetime.date(year + 1, 1, 1)
    total = 0
    for _d, _acct, amount in _iter_between(ledger, account, start, end):
        total += amount
    return int(total)

