    """Return True if `ledger` has at least one entry dated `day`."""
    if not isinstance(day, datetime.date):
        raise TypeError("day must be a datetime.date")

    # Iterate all entries and compare the entry date exactly.
    for entry_day, _account, _amount in ledger.entries():
        if entry_day == day:
            return True
    return False

