def range_total_dollars(ledger, account, first_day, last_day) -> float:
    if not isinstance(first_day, datetime.date) or not isinstance(last_day, datetime.date):
        raise TypeError("first_day and last_day must be datetime.date")
    if first_day > last_day:
        raise ValueError("first_day must be <= last_day")

    total = 0

    # Inclusive range via between(...)
    entries = ledger.between(first_day, last_day) if hasattr(ledger, "between") else [
        (d, acct, amt)
        for (d, acct, amt) in ledger.entries()
        if first_day <= d <= last_day
    ]

    for _, acct, amount in entries:
        if acct == account:
            total += amount

    # Convert cents->dollars only if the amounts are integer cents.
    if isinstance(total, int):
        return total / 100.0
    return float(total)

