def shift_right(shelf):
    """Move every item on `shelf` one slot later (wrap last->first)."""
    size = getattr(shelf, "size", None)
    if not size or size <= 0:
        return

    # kiln.Shelf uses 1-based slot indices for put/get.
    old = [shelf.get(i) for i in range(1, size + 1)]

    for i in range(1, size + 1):
        shelf.put(i, old[(i - 2) % size])

