def merge_desc(a, b):
    """Merge two (key, qty) sequences and return the merged result sorted by key descending."""
    aa = sorted(a, key=lambda pair: pair[0])
    bb = sorted(b, key=lambda pair: pair[0])
    merged = kiln.merge(aa, bb)
    return sorted(merged, key=lambda pair: pair[0], reverse=True)
